toolScript:
// --- HISTORY DATABASE ---
        const historicalEvents = [
            { year: 1969, month: 7, text: "Humans landed on the Moon (Apollo 11)" },
            { year: 1977, month: 5, text: "Star Wars Episode IV was released" },
            { year: 1980, month: 5, text: "Pac-Man was released in Japan" },
            { year: 1981, month: 8, text: "MTV launched" },
            { year: 1989, month: 11, text: "The Berlin Wall fell" },
            { year: 1990, month: 2, text: "Adobe Photoshop 1.0 was released" },
            { year: 1991, month: 12, text: "The World Wide Web became publicly available" },
            { year: 1994, month: 7, text: "Amazon was founded by Jeff Bezos" },
            { year: 1995, month: 8, text: "Windows 95 was released" },
            { year: 1997, month: 5, text: "Deep Blue defeated Garry Kasparov at Chess" },
            { year: 1998, month: 9, text: "Google was founded" },
            { year: 2001, month: 10, text: "Apple introduced the first iPod" },
            { year: 2004, month: 2, text: "Facebook launched at Harvard" },
            { year: 2005, month: 4, text: "The first YouTube video was uploaded" },
            { year: 2007, month: 1, text: "Steve Jobs unveiled the first iPhone" },
            { year: 2008, month: 11, text: "Bitcoin whitepaper was published" },
            { year: 2009, month: 5, text: "Minecraft was released to the public" },
            { year: 2012, month: 8, text: "Voyager 1 entered interstellar space" },
            { year: 2015, month: 12, text: "SpaceX landed a reusable rocket for the first time" },
            { year: 2016, month: 7, text: "Pokémon GO launched" },
            { year: 2020, month: 3, text: "The COVID-19 Pandemic was declared" },
            { year: 2022, month: 11, text: "ChatGPT was released, bringing AI to the mainstream" }
        ];
        let tickerInterval;
        let userBirthDate = null;
        function formatNumber(num) {
            return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
        }
        function calculateLifeStats() {
            const dateInput = document.getElementById('dob-input').value;
            if (!dateInput) {
                // We use standard alerts, but in a real app a toast would be nicer.
                // For simplicity here, alert is fine.
                alert("Please select your birth date.");
                return;
            }
            userBirthDate = new Date(dateInput);
            const now = new Date();
            if (userBirthDate > now) {
                alert("Are you a time traveler? Please select a date in the past.");
                return;
            }
            // UI Transition
            document.getElementById('input-screen').style.display = 'none';
            document.getElementById('results-screen').classList.remove('hidden-result');
            document.getElementById('results-screen').classList.add('visible-result');
            // Generate History
            generateHistory(userBirthDate);
            // Calculate Next Birthday
            calculateNextBirthday(userBirthDate);
            // Start the ticker
            if (tickerInterval) clearInterval(tickerInterval);
            updateTicker(); // Run immediately
            tickerInterval = setInterval(updateTicker, 1000);
        }
        function updateTicker() {
            if (!userBirthDate) return;
            const now = new Date();
            const diffInSeconds = (now - userBirthDate) / 1000;
            // Constants (Averages)
            const heartRateAvg = 80 / 60; // beats per second
            const breathRateAvg = 16 / 60; // breaths per second
            const earthSpeedKmS = 29.78; // km per second
            const dreamRate = 4; // approx dreams per night (very rough avg)
            const daysAlive = diffInSeconds / (60 * 60 * 24);
            // Update DOM
            document.getElementById('stat-seconds').innerText = formatNumber(Math.floor(diffInSeconds));
            document.getElementById('stat-heart').innerText = formatNumber(Math.floor(diffInSeconds * heartRateAvg));
            document.getElementById('stat-breaths').innerText = formatNumber(Math.floor(diffInSeconds * breathRateAvg));
            document.getElementById('stat-distance').innerText = formatNumber(Math.floor(diffInSeconds * earthSpeedKmS));
            document.getElementById('stat-dreams').innerText = formatNumber(Math.floor(daysAlive * dreamRate));
        }
        function generateHistory(birthDate) {
            const container = document.getElementById('history-feed');
            container.innerHTML = '';
            const relevantEvents = historicalEvents.filter(e => {
                const eventDate = new Date(e.year, e.month - 1, 1);
                return eventDate > birthDate;
            });
            if (relevantEvents.length === 0) {
                container.innerHTML = '<div class="text-slate-500 italic p-4 text-center">You are younger than our history database! You are the future.</div>';
                return;
            }
            // Sort by date (ascending)
            relevantEvents.sort((a, b) => a.year - b.year);
            relevantEvents.forEach((e) => {
                const eventDate = new Date(e.year, e.month - 1, 1);
                // Calculate how old user was
                let ageAtEvent = e.year - birthDate.getFullYear();
                if (birthDate.getMonth() > (e.month - 1)) ageAtEvent--;
                if (ageAtEvent < 0) ageAtEvent = 0; // Happened same year
                const html = `
                    <div class="flex gap-4 p-4 rounded-xl bg-slate-800 border border-slate-700 hover:bg-slate-700 transition-colors items-center group">
                        <div class="text-[#EE6C4D] font-mono font-bold whitespace-nowrap text-lg">${e.year}</div>
                        <div>
                            <div class="text-slate-200 font-medium group-hover:text-white transition-colors">${e.text}</div>
                            <div class="text-slate-500 text-[10px] uppercase tracking-wider mt-1 font-bold">Age: ${ageAtEvent}</div>
                        </div>
                    </div>
                `;
                container.insertAdjacentHTML('beforeend', html);
            });
        }
        function calculateNextBirthday(dob) {
            const now = new Date();
            let nextBday = new Date(now.getFullYear(), dob.getMonth(), dob.getDate());
            if (now > nextBday) {
                nextBday.setFullYear(now.getFullYear() + 1);
            }
            const diffTime = Math.abs(nextBday - now);
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            document.getElementById('stat-next-bday').innerText = `in ${diffDays} days`;
        }
        function resetTool() {
            clearInterval(tickerInterval);
            userBirthDate = null;
            document.getElementById('dob-input').value = '';
            document.getElementById('results-screen').classList.remove('visible-result');
            document.getElementById('results-screen').classList.add('hidden-result');
            // Allow animation to finish before hiding display
            setTimeout(() => {
                document.getElementById('input-screen').style.display = 'flex';
                document.getElementById('history-feed').innerHTML = ''; // Clear history
            }, 500);
        }
        // --- SCROLL LOGIC ---
